const state = flow.get('smartFarmState') || {
    pump_state: 'UNKNOWN', fan_state: 'UNKNOWN', led_state: 'UNKNOWN',
    pump_mode: 'AUTO', fan_mode: 'AUTO', led_mode: 'AUTO',
    pump_lock: true, lastSeen: {}, pending: {}
};
const topic = String(msg.topic || '');
const raw = String(msg.payload ?? '').trim();
const upper = raw.toUpperCase();
const now = Date.now();
let actuatorEvent = null;
let alertEvent = null;

const numericTopics = {
    'smartfarm/rsd2s3g3/module1/soil': 'soil_raw',
    'smartfarm/rsd2s3g3/module1/soil_percent': 'soil_percent',
    'smartfarm/rsd2s3g3/module2/temperature': 'temperature_c',
    'smartfarm/rsd2s3g3/module2/humidity': 'humidity_percent',
    'smartfarm/rsd2s3g3/module2/light': 'light_raw',
    'smartfarm/rsd2s3g3/module3/water': 'water_raw',
    'smartfarm/rsd2s3g3/module3/water_percent': 'water_level_percent',
    'smartfarm/rsd2s3g3/module4/yellowing': 'module4_yellowing',
    'smartfarm/rsd2s3g3/module4/risk': 'module4_risk'
};
if (numericTopics[topic]) {
    const value = Number(raw);
    if (Number.isFinite(value)) state[numericTopics[topic]] = value;
}

const modeTopics = {
    'smartfarm/rsd2s3g3/module1/pump/mode': 'pump_mode',
    'smartfarm/rsd2s3g3/control/pump/mode': 'pump_mode',
    'smartfarm/rsd2s3g3/module2/fan/mode': 'fan_mode',
    'smartfarm/rsd2s3g3/control/fan/mode': 'fan_mode',
    'smartfarm/rsd2s3g3/module2/led/mode': 'led_mode',
    'smartfarm/rsd2s3g3/control/led/mode': 'led_mode'
};
if (modeTopics[topic] && ['AUTO', 'MANUAL'].includes(upper)) state[modeTopics[topic]] = upper;
if (topic === 'smartfarm/rsd2s3g3/module3/pump_lock') state.pump_lock = upper === 'LOCKED';
if (topic === 'smartfarm/rsd2s3g3/module4/status') state.module4_status = upper;

const moduleMatch = topic.match(/^smartfarm\/rsd2s3g3\/module([1-4])\//);
if (moduleMatch) state.lastSeen[moduleMatch[1]] = now;

const controls = {
    'smartfarm/rsd2s3g3/control/pump': { actuator: 'PUMP', module_id: 1, stateKey: 'pump_state', modeKey: 'pump_mode' },
    'smartfarm/rsd2s3g3/control/fan': { actuator: 'FAN', module_id: 2, stateKey: 'fan_state', modeKey: 'fan_mode' },
    'smartfarm/rsd2s3g3/control/led': { actuator: 'GROW_LED', module_id: 2, stateKey: 'led_state', modeKey: 'led_mode' }
};
const feedback = {
    'smartfarm/rsd2s3g3/module1/pump': { actuator: 'PUMP', module_id: 1, stateKey: 'pump_state', modeKey: 'pump_mode' },
    'smartfarm/rsd2s3g3/module2/fan': { actuator: 'FAN', module_id: 2, stateKey: 'fan_state', modeKey: 'fan_mode' },
    'smartfarm/rsd2s3g3/module2/led': { actuator: 'GROW_LED', module_id: 2, stateKey: 'led_state', modeKey: 'led_mode' }
};

if (controls[topic] && ['ON', 'OFF'].includes(upper)) {
    const command = controls[topic];
    state.pending[command.actuator] = {
        requested_action: upper, module_id: command.module_id,
        control_mode: state[command.modeKey] || 'MANUAL', sent_at: now
    };
}
if (feedback[topic] && ['ON', 'OFF'].includes(upper)) {
    const result = feedback[topic];
    state[result.stateKey] = upper;
    const pending = state.pending[result.actuator];
    if (pending && now - pending.sent_at <= 20000) {
        const safetyRejected = result.actuator === 'PUMP' && pending.requested_action === 'ON' && state.pump_lock;
        actuatorEvent = { payload: {
            module_id: pending.module_id, actuator: result.actuator,
            requested_action: pending.requested_action, actual_state: upper,
            control_mode: pending.control_mode, command_source: 'DASHBOARD',
            result: safetyRejected ? 'REJECTED' : (pending.requested_action === upper ? 'ACCEPTED' : 'FAILED'),
            reason: safetyRejected ? 'Low-water safety lock' : 'MQTT feedback received by Node-RED'
        }};
        delete state.pending[result.actuator];
    }
}

if (topic === 'smartfarm/rsd2s3g3/module4/alert' && raw) {
    alertEvent = { payload: { module_id: 4, alert_type: 'CROP_HEALTH',
        severity: state.module4_status === 'RED' ? 'CRITICAL' : 'WARNING',
        message: raw, acknowledged: false } };
} else if (topic === 'smartfarm/rsd2s3g3/system/alert' && raw) {
    alertEvent = { payload: { module_id: null, alert_type: 'SYSTEM',
        severity: upper.includes('LOCK') ? 'CRITICAL' : 'WARNING',
        message: raw, acknowledged: false } };
}

flow.set('smartFarmState', state);
const decisionTopics = new Set([
    'smartfarm/rsd2s3g3/module1/soil', 'smartfarm/rsd2s3g3/module1/soil_percent',
    'smartfarm/rsd2s3g3/module2/humidity', 'smartfarm/rsd2s3g3/module3/pump_lock'
]);
const decisionTrigger = decisionTopics.has(topic) ? { topic, payload: state } : null;
return [actuatorEvent, alertEvent, decisionTrigger];

const state = flow.get('smartFarmState') || {};
const sensorKeys = ['soil_raw', 'soil_percent', 'temperature_c', 'humidity_percent', 'light_raw', 'water_raw', 'water_level_percent'];
const hasAnySensor = sensorKeys.some(key => Number.isFinite(state[key]));
if (!hasAnySensor) return null;
function ranged(value, minimum, maximum) {
    return Number.isFinite(value) && value >= minimum && value <= maximum ? value : null;
}
const complete = sensorKeys.every(key => Number.isFinite(state[key]));
msg.payload = {
    device_id: 'agrisense-rsd2s3g3-esp32',
    soil_raw: ranged(state.soil_raw, 0, 4095),
    soil_percent: ranged(state.soil_percent, 0, 100),
    temperature_c: ranged(state.temperature_c, -40, 85),
    humidity_percent: ranged(state.humidity_percent, 0, 100),
    light_raw: ranged(state.light_raw, 0, 4095),
    water_raw: ranged(state.water_raw, 0, 4095),
    water_level_percent: ranged(state.water_level_percent, 0, 100),
    pump_state: state.pump_state || 'UNKNOWN', fan_state: state.fan_state || 'UNKNOWN',
    led_state: state.led_state || 'UNKNOWN', pump_mode: state.pump_mode || 'AUTO',
    fan_mode: state.fan_mode || 'AUTO', led_mode: state.led_mode || 'AUTO',
    pump_lock: Boolean(state.pump_lock),
    data_quality: complete ? 'VALID' : 'SUSPECT',
    metadata: { source: 'node-red', mqtt_broker: 'broker.hivemq.com', snapshot_complete: complete }
};
return msg;

const base = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_PUBLISHABLE_KEY');
if (!base || !key) { node.error('Missing Supabase environment variables', msg); return null; }
msg.method = 'POST';
msg.url = base.replace(/\/$/, '') + '/rest/v1/sensor_data';
msg.headers = {
    apikey: key,
    Authorization: 'Bearer ' + key,
    'Content-Type': 'application/json',
    Prefer: 'return=minimal'
};
msg.payload = JSON.stringify(msg.payload);
return msg;

const state = flow.get('smartFarmState') || { lastSeen: {} };
const now = Date.now();
const names = {
    1: 'Irrigation',
    2: 'Environment Monitoring',
    3: 'Water Tank and Resource Management',
    4: 'Crop Health and Visual Monitoring'
};
const updates = Object.keys(names).map(id => {
    const lastSeen = state.lastSeen?.[id];
    const healthy = lastSeen && now - lastSeen <= 45000;
    return {
        moduleId: Number(id),
        payload: {
            module_name: names[id],
            health_status: healthy ? 'HEALTHY' : 'OFFLINE',
            error_code: healthy ? null : 'NO_RECENT_MQTT',
            message: healthy ? 'Recent MQTT data received' : 'No MQTT data in the last 45 seconds',
            last_seen: lastSeen ? new Date(lastSeen).toISOString() : null
        }
    };
});
return [updates];

const base = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_PUBLISHABLE_KEY');
if (!base || !key) { node.error('Missing Supabase environment variables', msg); return null; }
msg.method = 'PATCH';
msg.url = base.replace(/\/$/, '') + '/rest/v1/module_status?module_id=eq.' + msg.moduleId;
msg.headers = {
    apikey: key,
    Authorization: 'Bearer ' + key,
    'Content-Type': 'application/json',
    Prefer: 'return=minimal'
};
msg.payload = JSON.stringify(msg.payload);
return msg;

const base = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_PUBLISHABLE_KEY');
if (!base || !key) { node.error('Missing Supabase environment variables', msg); return null; }
msg.method = 'POST';
msg.url = base.replace(/\/$/, '') + '/rest/v1/actuator_events';
msg.headers = { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
msg.payload = JSON.stringify(msg.payload);
return msg;

const base = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_PUBLISHABLE_KEY');
if (!base || !key) { node.error('Missing Supabase environment variables', msg); return null; }
msg.method = 'POST';
msg.url = base.replace(/\/$/, '') + '/rest/v1/alerts';
msg.headers = { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
msg.payload = JSON.stringify(msg.payload);
return msg;

const state = flow.get('smartFarmState') || {};
state.source = String(msg.payload || '');
state.sourceSeen = Date.now();
flow.set('smartFarmState', state);
return null;

const state = flow.get('smartFarmState') || {};
const simulated = state.source === 'pc-simulator' && Date.now() - Number(state.sourceSeen || 0) < 10000;
if (simulated) {
    msg.payload.device_id = 'pc-simulator';
    msg.payload.metadata.source = 'pc-simulator-via-node-red';
    msg.payload.metadata.simulated = true;
}
return msg;

const allowedKinds = ['sensor_data', 'actuator_events', 'alerts'];
if (!allowedKinds.includes(msg.writeKind) || !msg.payload) return null;

let counter = Number(flow.get('supabaseEventCounter') || 0);
counter = (counter + 1) % 1000;
flow.set('supabaseEventCounter', counter);

const databaseId = Date.now() * 1000 + counter;
const body = { ...msg.payload, id: databaseId };
if (msg.writeKind === 'sensor_data') {
    body.metadata = { ...(body.metadata || {}), queue_event_id: String(databaseId) };
}

const record = {
    queueId: String(databaseId),
    kind: msg.writeKind,
    body,
    queuedAt: new Date().toISOString(),
    attempts: 0,
    lastAttempt: Date.now(),
    nextAttempt: Date.now()
};

const queue = flow.get('supabaseQueue') || [];
queue.push(record);
flow.set('supabaseQueue', queue);

msg.queueId = record.queueId;
msg.writeRecord = record;
const queueStatus = { topic: 'smartfarm/rsd2s3g3/system/queue', payload: String(queue.length), retain: false };
return [msg, queueStatus];

const base = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_PUBLISHABLE_KEY');
const record = msg.writeRecord;
if (!record) return [null, null];

if (!base || !key) {
    msg.statusCode = 0;
    msg.error = { message: 'Missing Supabase environment variables' };
    return [null, msg];
}

msg.method = 'POST';
msg.url = base.replace(/\/$/, '') + '/rest/v1/' + record.kind + '?on_conflict=id';
msg.headers = {
    apikey: key,
    Authorization: 'Bearer ' + key,
    'Content-Type': 'application/json',
    Prefer: 'resolution=ignore-duplicates,return=minimal'
};
msg.payload = JSON.stringify(record.body);
msg.queueId = record.queueId;
return [msg, null];

const statusCode = Number(msg.statusCode || 0);
const success = statusCode >= 200 && statusCode < 300;
const now = Date.now();
let queue = flow.get('supabaseQueue') || [];

if (msg.queueId) {
    const index = queue.findIndex(item => item.queueId === String(msg.queueId));
    if (index >= 0 && success) {
        queue.splice(index, 1);
    } else if (index >= 0) {
        const item = queue[index];
        item.attempts = Number(item.attempts || 0) + 1;
        item.lastAttempt = now;
        item.nextAttempt = now + Math.min(300000, 15000 * Math.pow(2, Math.min(item.attempts - 1, 5)));
        item.lastError = msg.error?.message || msg.payload || ('HTTP ' + statusCode);
    }
    flow.set('supabaseQueue', queue);
}

if (success) flow.set('supabaseLastSuccess', new Date().toISOString());
const lastSuccess = flow.get('supabaseLastSuccess') || null;
const cloudPayload = {
    status: success ? 'ONLINE' : 'OFFLINE',
    queue: queue.length,
    lastSuccess,
    lastError: success ? null : (msg.error?.message || String(msg.payload || 'Connection failed'))
};

const cloudStatus = { topic: 'smartfarm/rsd2s3g3/system/cloud', payload: JSON.stringify(cloudPayload), retain: false };
const queueStatus = { topic: 'smartfarm/rsd2s3g3/system/queue', payload: String(queue.length), retain: false };
return [[cloudStatus, queueStatus]];

const now = Date.now();
const queue = flow.get('supabaseQueue') || [];
const due = [];
for (const item of queue) {
    if (due.length >= 10) break;
    if (Number(item.nextAttempt || 0) <= now) {
        item.lastAttempt = now;
        due.push({ queueId: item.queueId, writeRecord: item });
    }
}
flow.set('supabaseQueue', queue);
const queueStatus = { topic: 'smartfarm/rsd2s3g3/system/queue', payload: String(queue.length), retain: false };
return [due, queueStatus];

const latitude = env.get('WEATHER_LATITUDE') || '3.1390';
const longitude = env.get('WEATHER_LONGITUDE') || '101.6869';
msg.method = 'GET';
msg.url = 'https://api.open-meteo.com/v1/forecast?latitude=' + encodeURIComponent(latitude)
    + '&longitude=' + encodeURIComponent(longitude)
    + '&hourly=precipitation_probability,rain&forecast_days=2&timezone=GMT';
return msg;

const body = msg.payload || {};
const times = body.hourly?.time;
const probabilities = body.hourly?.precipitation_probability;
const rain = body.hourly?.rain;
if (!Array.isArray(times) || !Array.isArray(probabilities) || !Array.isArray(rain)) {
    flow.set('weatherState', { status: 'ERROR', updatedAt: Date.now() });
    return [[{ topic: 'smartfarm/rsd2s3g3/weather/status', payload: 'ERROR', retain: true }], { payload: 'weather-error' }];
}
const now = Date.now();
const indices = times.map((time, index) => ({ index, time: Date.parse(time + 'Z') }))
    .filter(item => item.time >= now).slice(0, 6).map(item => item.index);
if (!indices.length) return null;
const maxProbability = Math.max(...indices.map(index => Number(probabilities[index]) || 0));
const rainMm = indices.reduce((sum, index) => sum + (Number(rain[index]) || 0), 0);
const settings = Object.assign({ rainProbability: 65 }, flow.get('automationSettings') || {});
const rainExpected = maxProbability >= Number(settings.rainProbability) || rainMm >= 1;
const weather = { status: 'OK', maxProbability, rainMm, rainExpected, updatedAt: now };
flow.set('weatherState', weather);
const messages = [
    { topic: 'smartfarm/rsd2s3g3/weather/rain_probability', payload: String(maxProbability), retain: true },
    { topic: 'smartfarm/rsd2s3g3/weather/rain_expected', payload: rainExpected ? 'TRUE' : 'FALSE', retain: true },
    { topic: 'smartfarm/rsd2s3g3/weather/status', payload: 'OK', retain: true }
];
return [messages, { payload: 'weather-updated' }];

const state = flow.get('smartFarmState') || {};
const weather = flow.get('weatherState') || {};
const settings = Object.assign({ soilStart: 30, soilStop: 45, rainProbability: 65, humidityDelay: 85 }, flow.get('automationSettings') || {});
const soilStart = Number(settings.soilStart);
const soilStop = Number(settings.soilStop) > soilStart ? Number(settings.soilStop) : 45;
const humidityDelay = Number(settings.humidityDelay);
const rainExpected = Number(weather.maxProbability || 0) >= Number(settings.rainProbability) || Number(weather.rainMm || 0) >= 1;
const now = Date.now();
let decision = 'OFF';
let rule = 'SAFE-OFF';
let soilDemand = String(flow.get('irrigationSoilDemand') || 'OFF');
const soilFresh = state.lastSeen?.['1'] && now - state.lastSeen['1'] <= 45000;
const weatherFresh = weather.status === 'OK' && now - Number(weather.updatedAt || 0) <= 20 * 60 * 1000;
if (Number.isFinite(state.soil_percent)) {
    if (state.soil_percent < soilStart) soilDemand = 'ON';
    else if (state.soil_percent >= soilStop) soilDemand = 'OFF';
    flow.set('irrigationSoilDemand', soilDemand);
}
if (state.pump_lock) {
    decision = 'OFF'; rule = 'LOW-WATER-LOCK';
} else if (!soilFresh || !Number.isFinite(state.soil_percent)) {
    decision = 'LOCAL'; rule = 'SOIL-DATA-STALE-LOCAL-FALLBACK';
} else if (!weatherFresh) {
    decision = 'LOCAL'; rule = 'WEATHER-DATA-STALE-LOCAL-FALLBACK';
} else if (soilDemand === 'OFF') {
    decision = 'OFF'; rule = state.soil_percent >= soilStop ? 'SOIL-WET' : 'SOIL-RECOVERY';
} else if (rainExpected || Number(state.humidity_percent) >= humidityDelay) {
    decision = 'DELAY'; rule = rainExpected ? 'RAIN-EXPECTED' : 'HIGH-HUMIDITY';
} else {
    decision = 'ON'; rule = state.soil_percent < soilStart ? 'DRY-NO-RAIN' : 'SOIL-HYSTERESIS';
}
return [[
    { topic: 'smartfarm/rsd2s3g3/control/pump/auto', payload: decision, retain: true },
    { topic: 'smartfarm/rsd2s3g3/module1/irrigation_rule', payload: rule, retain: true },
    { topic: 'smartfarm/rsd2s3g3/weather/rain_expected', payload: rainExpected ? 'TRUE' : 'FALSE', retain: true }
]];

const defaults = { soilStart: 30, soilStop: 45, rainProbability: 65, humidityDelay: 85 };
const definitions = {
    'smartfarm/rsd2s3g3/config/soil/pump_on_percent': ['soilStart', 5, 60],
    'smartfarm/rsd2s3g3/config/soil/pump_off_percent': ['soilStop', 10, 90],
    'smartfarm/rsd2s3g3/config/irrigation/rain_probability': ['rainProbability', 0, 100],
    'smartfarm/rsd2s3g3/config/irrigation/humidity_percent': ['humidityDelay', 50, 100]
};
const definition = definitions[String(msg.topic || '')];
if (!definition) return null;
const value = Number(msg.payload);
if (!Number.isFinite(value) || value < definition[1] || value > definition[2]) {
    node.warn('Rejected invalid automation setting on ' + msg.topic);
    return null;
}
const settings = Object.assign({}, defaults, flow.get('automationSettings') || {});
settings[definition[0]] = value;
flow.set('automationSettings', settings);
node.status({ fill: 'green', shape: 'dot', text: definition[0] + '=' + value });
return { topic: msg.topic, payload: settings };

const topics = {
    'smartfarm/rsd2s3g3/module3/pump_runtime_seconds': 'pump_runtime_seconds',
    'smartfarm/rsd2s3g3/module3/estimated_water_litres': 'estimated_water_litres'
};
const key = topics[String(msg.topic || '')];
if (!key) return null;
const value = Number(msg.payload);
if (!Number.isFinite(value) || value < 0) {
    node.warn('Rejected invalid pump resource estimate on ' + msg.topic);
    return null;
}
const estimates = flow.get('pumpResourceEstimates') || {};
estimates[key] = value;
estimates.updated_at = Date.now();
flow.set('pumpResourceEstimates', estimates);
return null;

const estimates = flow.get('pumpResourceEstimates') || {};
const runtime = Number(estimates.pump_runtime_seconds);
const litres = Number(estimates.estimated_water_litres);
msg.payload.pump_runtime_seconds = Number.isFinite(runtime) && runtime >= 0 ? Math.round(runtime) : null;
msg.payload.estimated_water_litres = Number.isFinite(litres) && litres >= 0 ? Number(litres.toFixed(3)) : null;
msg.payload.metadata.resource_estimate_complete = msg.payload.pump_runtime_seconds !== null && msg.payload.estimated_water_litres !== null;
msg.payload.metadata.water_usage_basis = 'pump runtime multiplied by prototype flow estimate; no flow sensor';
return msg;
